function show_flash(){if(isset($_SESSION['flash'])){$f=$_SESSION['flash'];unset($_SESSION['flash']);$type=in_array($f['type'],['success','error','warning','info'],true)?$f['type']:'info';echo '<div role="status" class="alert '.e($type).' civic-flash" data-civic-flash="'.e($type).'">'.e($f['message']).'</div>';}}
