function empty_state($text='No reports found.'){echo '<div class="empty"><span>⌖</span><h3>'.e($text).'</h3><p>Try another filter or help your community by reporting an issue.</p></div>';}
function issue_card($i){?><article class="issue-card"><a class="card-image" href="index.php?page=issue&id=<?=$i['id']?>"><?php report_photo($i,'',true); ?><span class="photo-category"><?=e($i['category'])?></span></a><div class="card-body"><div class="row between"><?=badge($i['status'])?><small class="muted">#<?=str_pad($i['id'],4,'0',STR_PAD_LEFT)?></small></div><h3><a href="index.php?page=issue&id=<?=$i['id']?>"><?=e($i['title'])?></a></h3><p class="address">⌖ <?=e($i['address'])?></p><div class="card-footer"><span><?=date('d M Y',strtotime($i['created_at']))?></span><span>♡ <?=$i['support_count']?> supporting</span></div></div></article><?php }
function issue_table($rows) {if(!$rows){empty_state();return;}?><div class="table-wrap"><table><thead><tr><th>Report</th><th>Category</th><th>Status</th><th>Officer</th><th>Reported</th></tr></thead><tbody><?php foreach($rows as $i):?><tr><td><a class="table-title" href="index.php?page=issue&id=<?=$i['id']?>"><small>#<?=$i['id']?></small><?=e($i['title'])?></a></td><td><?=e($i['category'])?></td><td><?=badge($i['status'])?></td><td><?=e($i['officer']?:'Unassigned')?></td><td><?=date('d M Y',strtotime($i['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php }

